export class BookService {
  constructor(private repo: BookRepository) {}

  async createBook(payload: { title: string; author: string }, userId: string) {
    if (!payload.title) throw new Error('VALIDATION_ERROR: Title is required');
    return await this.repo.insert({ ...payload, userId });
  }
}

