export class BookRepository {
  async insert(record: { title: string; author: string; userId: string }) {
    return await db.query('INSERT INTO books (title, author, user_id) VALUES ($1, $2, $3) RETURNING *', [
      record.title,
      record.author,
      record.userId
    ]);
  }
}

