type BookHandler struct {
    service *BookService
}

func (h *BookHandler) CreateBook(w http.ResponseWriter, r *http.Request) {
    // Read trusted claims from context (populated by Auth Middleware)
    userId, ok := r.Context().Value("userId").(string)
    if !ok {
        http.Error(w, "401 Unauthorized", http.StatusUnauthorized)
        return
    }

    var req CreateBookRequest
    if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
        http.Error(w, "400 Bad Request: Invalid JSON", http.StatusBadRequest)
        return
    }

    book, err := h.service.CreateBook(r.Context(), req, userId)
    if err != nil {
        http.Error(w, err.Error(), http.StatusInternalServerError)
        return
    }

    w.WriteHeader(http.StatusCreated)
    json.NewEncoder(w).Encode(book)
}

// 2. Service Layer (HTTP Agnostic)
type BookService struct {
    repo *BookRepository
}

func (s *BookService) CreateBook(ctx context.Context, req CreateBookRequest, userId string) (*Book, error) {
    return s.repo.Insert(ctx, req.Title, req.Author, userId)
